const pointer = $('Read active request').first().json;
const health = $('Read ops snapshot').first().json;
const expectedRun = String(pointer.golden_path_run_id ?? '');
const observedRun = String(health.canonical?.golden_path_run_id ?? health.run?.id ?? '');
const sameRequest = pointer.request_id && pointer.request_id === health.canonical?.request_id;
const sameRun = expectedRun && expectedRun === observedRun;
return [{ json: {
  mode: 'READ_ONLY_SHADOW',
  request_id: pointer.request_id ?? null,
  active_pointer_state: pointer.state ?? null,
  expected_run_id: expectedRun || null,
  health_run_id: observedRun || null,
  health_snapshot_generated_at: health.generated_at ?? null,
  health_snapshot_stale_or_unbound: !(sameRequest && sameRun),
  displayed_health_state: sameRequest && sameRun ? health.run?.status ?? 'unknown' : 'UNVERIFIED_SNAPSHOT',
  review_delivery: 'NOT_VERIFIED',
  publication: 'NOT_VERIFIED',
  note: 'Observer does not validate final QA artifacts or authenticated Telegram/platform receipts. Never infer success from workflow conclusion or green status.'
}}];
